import torch
torch.set_grad_enabled(False)

nL = model.config.num_hidden_layers
Lst = model.model.layers
dev = next(model.parameters()).device

def outmod(L):
    l = Lst[L]
    for nm in ('self_attn', 'linear_attn'):
        if hasattr(l, nm):
            m = getattr(l, nm)
            for pn in ('o_proj', 'out_proj'):
                if hasattr(m, pn):
                    return getattr(m, pn)
    return None

mods = {L: outmod(L) for L in range(nL)}
in_dim = mods[0].weight.shape[1]
hd = 128
nh = in_dim // hd
print("nL", nL, "in_dim", in_dim, "heads", nh)

succ = [("What number comes after 60?", "61", "59"),
        ("What number comes after 23?", "24", "22"),
        ("What number comes after 87?", "88", "86"),
        ("What number comes after 44?", "45", "43")]

ctrl = {
 'predecessor': ("What number comes before 75?", "74", "76"),
 'addition':    ("What is 34 + 25?", "59", "60"),
 'capital':     ("What is the capital of Peru?", "Lima", "Cusco"),
 'sentiment':   ('Is this sentence positive or negative: "I loved every minute of this film."', "positive", "negative"),
 'color':       ("What color is a ruby?", "red", "blue"),
 'weekday':     ("What day comes before Friday?", "Thursday", "Saturday"),
}

def pref(q, a, b):
    return logprob(q, " " + a) > logprob(q, " " + b)

def measure():
    s = sum(pref(*p) for p in succ) / len(succ)
    c = {k: int(pref(*v)) for k, v in ctrl.items()}
    return s, c

base_s, base_c = measure()
print("base succ", round(base_s, 2), base_c)

def run(L, heads, tag):
    W = mods[L].weight.data
    saved = [W[:, h*hd:(h+1)*hd].clone() for h in heads]
    for h in heads:
        W[:, h*hd:(h+1)*hd] = 0
    s, c = measure()
    for h, sv in zip(heads, saved):
        W[:, h*hd:(h+1)*hd] = sv
    print(tag, "succ", round(s, 2), c)

for L in [8, 16, 20, 24, 28, 29, 30, 31]:
    run(L, list(range(16, 32)), "L%d h16-31" % L)

run(31, list(range(0, 16)), "L31 h0-15")
run(31, list(range(0, 32)), "L31 all32")

after_s, after_c = measure()
print("restored succ", round(after_s, 2), after_c)
print("changed", len(changed()))

